package codebuddy

import (
	"encoding/json"

	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// CodeBuddySettings represents the .codebuddy/settings.json structure.
type CodeBuddySettings struct {
	Hooks CodeBuddyHooks `json:"hooks"`
}

// CodeBuddyHooks contains the hook configurations.
type CodeBuddyHooks struct {
	SessionStart     []CodeBuddyHookMatcher `json:"SessionStart,omitempty"`
	SessionEnd       []CodeBuddyHookMatcher `json:"SessionEnd,omitempty"`
	UserPromptSubmit []CodeBuddyHookMatcher `json:"UserPromptSubmit,omitempty"`
	Stop             []CodeBuddyHookMatcher `json:"Stop,omitempty"`
	PreToolUse       []CodeBuddyHookMatcher `json:"PreToolUse,omitempty"`
	PostToolUse      []CodeBuddyHookMatcher `json:"PostToolUse,omitempty"`
}

// CodeBuddyHookMatcher matches hooks to specific patterns.
type CodeBuddyHookMatcher struct {
	Matcher string               `json:"matcher"`
	Hooks   []CodeBuddyHookEntry `json:"hooks"`
}

// CodeBuddyHookEntry represents a single hook command.
type CodeBuddyHookEntry struct {
	Type    string `json:"type"`
	Command string `json:"command"`
}

// sessionInfoRaw is the JSON structure from SessionStart/SessionEnd/Stop hooks.
// SessionStart includes a "model" field with the LLM model identifier.
type sessionInfoRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Model          string `json:"model,omitempty"`
}

// userPromptSubmitRaw is the JSON structure from UserPromptSubmit hooks.
type userPromptSubmitRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Prompt         string `json:"prompt"`
}

// taskHookInputRaw is the JSON structure from PreToolUse[Task] hook.
type taskHookInputRaw struct {
	SessionID      string          `json:"session_id"`
	TranscriptPath string          `json:"transcript_path"`
	ToolUseID      string          `json:"tool_use_id"`
	ToolInput      json.RawMessage `json:"tool_input"`
}

// postToolHookInputRaw is the JSON structure from PostToolUse hooks.
type postToolHookInputRaw struct {
	SessionID      string          `json:"session_id"`
	TranscriptPath string          `json:"transcript_path"`
	ToolUseID      string          `json:"tool_use_id"`
	ToolInput      json.RawMessage `json:"tool_input"`
	ToolResponse   struct {
		AgentID string `json:"agentId"`
	} `json:"tool_response"`
}

// Tool names used in CodeBuddy transcripts (same as Claude Code).
const (
	ToolWrite        = "Write"
	ToolEdit         = "Edit"
	ToolNotebookEdit = "NotebookEdit"
	ToolMCPWrite     = "mcp__acp__Write" //nolint:gosec // G101: This is a tool name, not a credential
	ToolMCPEdit      = "mcp__acp__Edit"
)

// FileModificationTools lists tools that create or modify files.
var FileModificationTools = []string{
	ToolWrite,
	ToolEdit,
	ToolNotebookEdit,
	ToolMCPWrite,
	ToolMCPEdit,
}

// messageUsage represents token usage from an API response.
type messageUsage struct {
	InputTokens              int `json:"input_tokens"`
	CacheCreationInputTokens int `json:"cache_creation_input_tokens"`
	CacheReadInputTokens     int `json:"cache_read_input_tokens"`
	OutputTokens             int `json:"output_tokens"`
}

// messageWithUsage represents an assistant message with usage data.
type messageWithUsage struct {
	ID    string       `json:"id"`
	Usage messageUsage `json:"usage"`
}

// extractModifiedFiles extracts files modified by tool calls from transcript lines.
func extractModifiedFiles(lines []transcript.Line) []string {
	fileSet := make(map[string]bool)
	var files []string

	for _, line := range lines {
		if line.Type != "assistant" {
			continue
		}

		var msg transcript.AssistantMessage
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type != "tool_use" {
				continue
			}

			isModifyTool := false
			for _, name := range FileModificationTools {
				if block.Name == name {
					isModifyTool = true
					break
				}
			}
			if !isModifyTool {
				continue
			}

			var input transcript.ToolInput
			if err := json.Unmarshal(block.Input, &input); err != nil {
				continue
			}

			file := input.FilePath
			if file == "" {
				file = input.NotebookPath
			}

			if file != "" && !fileSet[file] {
				fileSet[file] = true
				files = append(files, file)
			}
		}
	}

	return files
}

