package codebuddy

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// Compile-time interface assertions.
var (
	_ agent.TranscriptAnalyzer = (*CodeBuddyAgent)(nil)
	_ agent.TokenCalculator    = (*CodeBuddyAgent)(nil)
	_ agent.HookResponseWriter = (*CodeBuddyAgent)(nil)
)

// WriteHookResponse outputs a JSON hook response to stdout.
// CodeBuddy uses the same JSON systemMessage protocol as Claude Code.
func (c *CodeBuddyAgent) WriteHookResponse(message string) error {
	resp := struct {
		SystemMessage string `json:"systemMessage,omitempty"`
	}{SystemMessage: message}
	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
		return fmt.Errorf("failed to encode hook response: %w", err)
	}
	return nil
}

// HookNames returns the hook verbs CodeBuddy supports.
// These become subcommands: entire hooks codebuddy <verb>
func (c *CodeBuddyAgent) HookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNameSessionEnd,
		HookNameStop,
		HookNameUserPromptSubmit,
		HookNamePreTask,
		HookNamePostTask,
		HookNamePostTodo,
	}
}

// ParseHookEvent translates a CodeBuddy hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (c *CodeBuddyAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return c.parseSessionStart(stdin)
