		hookCommandExists(settings.Hooks.Stop, "go run ${CODEBUDDY_PROJECT_DIR}/cmd/entire/main.go hooks codebuddy stop")
}

// Helper functions for hook management

func hookCommandExists(matchers []CodeBuddyHookMatcher, command string) bool {
	for _, matcher := range matchers {
		for _, hook := range matcher.Hooks {
			if hook.Command == command {
				return true
			}
		}
	}
	return false
}

func hookCommandExistsWithMatcher(matchers []CodeBuddyHookMatcher, matcherName, command string) bool {
	for _, matcher := range matchers {
		if matcher.Matcher == matcherName {
			for _, hook := range matcher.Hooks {
				if hook.Command == command {
					return true
				}
			}
		}
	}
	return false
}

func addHookToMatcher(matchers []CodeBuddyHookMatcher, matcherName, command string) []CodeBuddyHookMatcher {
	entry := CodeBuddyHookEntry{
		Type:    "command",
		Command: command,
	}

	if matcherName == "" {
		for i, matcher := range matchers {
			if matcher.Matcher == "" {
				matchers[i].Hooks = append(matchers[i].Hooks, entry)
				return matchers
			}
		}
		return append(matchers, CodeBuddyHookMatcher{
			Matcher: "",
			Hooks:   []CodeBuddyHookEntry{entry},
		})
	}

	for i, matcher := range matchers {
		if matcher.Matcher == matcherName {
			matchers[i].Hooks = append(matchers[i].Hooks, entry)
			return matchers
		}
	}

	return append(matchers, CodeBuddyHookMatcher{
		Matcher: matcherName,
		Hooks:   []CodeBuddyHookEntry{entry},
	})
}

func isEntireHook(command string) bool {
	for _, prefix := range entireHookPrefixes {
		if strings.HasPrefix(command, prefix) {
			return true
		}
	}
	return false
}

func removeEntireHooks(matchers []CodeBuddyHookMatcher) []CodeBuddyHookMatcher {
	result := make([]CodeBuddyHookMatcher, 0, len(matchers))
	for _, matcher := range matchers {
		filteredHooks := make([]CodeBuddyHookEntry, 0, len(matcher.Hooks))
		for _, hook := range matcher.Hooks {
			if !isEntireHook(hook.Command) {
				filteredHooks = append(filteredHooks, hook)
			}
		}
		if len(filteredHooks) > 0 {
			matcher.Hooks = filteredHooks
			result = append(result, matcher)
		}
	}
	return result
}

